"""Write src/characters/badger/spots.ts from the tracer outputs (body spots + head/front-neck markings)."""
import json
import sys

left = json.load(open(sys.argv[1]))
heads = json.load(open(sys.argv[2])) if len(sys.argv) > 3 else {'head': [], 'frontNeck': []}
out = sys.argv[-1]


def q(s):
    return json.dumps(s)


L = []
L.append('''/**
 * BADGER coat markings, v1 (frozen). GENERATED by dev/trace/gen_left.py + gen_heads.py + emit_spots.py from
 * traces over the approved sheet crops. Do not add, remove or move markings here by hand:
 * PROJECT_INSTRUCTIONS.md freezes the approved simplified coat pattern.
 *
 * Body spots come from the LEFT coat map (reference/crops/badger_coat_left.png). Each record's `path` is a
 * cubic-bezier path in its PART's local coordinates (origin = that part's pivot, world units, ZOO = 900) for
 * the left-side view, and it is rendered inside that part's group, clipped to the part outline, so it
 * moves with the part and can never slide or jump sides. No randomness anywhere.
 * `ref` is the spot centre in the reference crop (2x sheet pixels) for QA.
 */
export type BadgerPartId =
	| 'torso'
	| 'neck'
	| 'legFrontNear'
	| 'legFrontFar'
	| 'legHindNear'
	| 'legHindFar'
	| 'tail'
	| 'head'
	| 'frontNeck';

export type BadgerSpot = {
	readonly id: string;
	/** Anatomical side the marking lives on. */
	readonly side: 'left' | 'right' | 'midline';
	readonly part: BadgerPartId;
	/** Leg segment for leg spots. */
	readonly segment?: 'upper' | 'lower' | 'paw';
	readonly path: string;
	readonly ref: {readonly crop: string; readonly x: number; readonly y: number};
	readonly desc: string;
};

/** Spots counted on badger_coat_left.png: 11 (1 large withers patch + 10 smaller spots). */
export const LEFT_SPOT_COUNT = 11;
''')
L.append('export const LEFT_SPOTS: readonly BadgerSpot[] = [')
for s in left:
    seg = ("\n\t\tsegment: %s," % q(s['segment'])) if s.get('segment') else ''
    L.append('''\t{
\t\tid: %s,
\t\tside: 'left',
\t\tpart: %s,%s
\t\tpath: %s,
\t\tref: {crop: %s, x: %d, y: %d},
\t\tdesc: %s,
\t},''' % (q(s['id']), q(s['part']), seg, q(s['path']), q(s['ref']['crop']), s['ref']['x'], s['ref']['y'], q(s['desc'])))
L.append('];')
L.append('')
L.append('''export const spotsFor = (part: BadgerPartId, spots: readonly BadgerSpot[] = LEFT_SPOTS): readonly BadgerSpot[] =>
\tspots.filter((s) => s.part === part);
''')

L.append('''/**
 * HEAD markings (front head controls facial markings and which ear is dark).
 * H-EAR-L-CAP: the dark cap is the whole outer flap of the ANATOMICAL LEFT ear (screen right in the front
 *   head; the near ear in left-facing views; the far ear in right-facing views). It is implemented as that
 *   ear's fill colour in every head view (see parts/heads), not as a path.
 * The remaining H- markings are spots; `paths` gives the path per head view in that view's head-local space
 * (views where the marking is hidden are absent).
 */
export type HeadMarking = {
	readonly id: string;
	readonly side: 'left' | 'right';
	readonly desc: string;
	readonly paths: Partial<Record<string, string>>;
};
''')
L.append('export const HEAD_MARKINGS: readonly HeadMarking[] = [')
for m in heads['head']:
    paths = ',\n'.join('\t\t\t%s: %s' % (k, q(v)) for k, v in m['paths'].items())
    L.append('''\t{
\t\tid: %s,
\t\tside: %s,
\t\tdesc: %s,
\t\tpaths: {
%s,
\t\t},
\t},''' % (q(m['id']), q(m['side']), q(m['desc']), paths) if paths else '''\t{
\t\tid: %s,
\t\tside: %s,
\t\tdesc: %s,
\t\tpaths: {},
\t},''' % (q(m['id']), q(m['side']), q(m['desc'])))
L.append('];')
L.append('')
L.append('''export const headMarkingPath = (id: string, view: string): string | undefined =>
\tHEAD_MARKINGS.find((m) => m.id === id)?.paths[view];
''')
L.append('''/**
 * Neck spots as seen in the FRONT bust (used by front heads / expression sheets). L-NECK is the same
 * marking as the left-view record above; R-NECK is the right-side neck spot (badger_coat_right.png,
 * below the pale ear). Paths are in the front-neck part's local space.
 */''')
L.append('export const FRONT_NECK_SPOTS: readonly BadgerSpot[] = [')
for s in heads['frontNeck']:
    L.append('''\t{
\t\tid: %s,
\t\tside: %s,
\t\tpart: 'frontNeck',
\t\tpath: %s,
\t\tref: {crop: %s, x: %d, y: %d},
\t\tdesc: %s,
\t},''' % (q(s['id']), q(s['side']), q(s['path']), q(s['ref']['crop']), s['ref']['x'], s['ref']['y'], q(s['desc'])))
L.append('];')
open(out, 'w').write('\n'.join(L) + '\n')
print('wrote', out)
